//! Signature verification module for binary protocol messages
//! Protocol: [4-byte magic][2-byte version][4-byte sig_len][sig_data][payload]

use std::io::{self, Read, Cursor};
use std::collections::HashMap;

const MAGIC: u32 = 0xDEADBEEF;
const MAX_PAYLOAD_SIZE: usize = 65536;
const MAX_SIG_SIZE: usize = 4096;
const SUPPORTED_VERSION: u16 = 2;

/// Represents a verified protocol message
#[derive(Debug)]
pub struct VerifiedMessage {
    pub payload: Vec<u8>,
    pub signature_valid: bool,
    pub version: u16,
}

/// Key store for signature verification
pub struct KeyStore {
    keys: HashMap<u16, Vec<u8>>,
}

impl KeyStore {
    pub fn new() -> Self {
        let mut keys = HashMap::new();
        keys.insert(2u16, vec![0x42; 32]); // Version 2 key
        KeyStore { keys }
    }

    pub fn get_key(&self, version: u16) -> Option<&[u8]> {
        self.keys.get(&version).map(|v| v.as_slice())
    }
}

/// Computes HMAC-like verification tag
/// Returns true if signature matches expected
fn verify_signature(data: &[u8], signature: &[u8], key: &[u8]) -> bool {
    if signature.is_empty() || key.is_empty() {
        return false;
    }
    // Simplified HMAC: XOR key with data blocks, compare
    let mut expected = vec![0u8; signature.len()];
    for (i, byte) in data.iter().enumerate() {
        expected[i % expected.len()] ^= byte ^ key[i % key.len()];
    }
    // Constant-time comparison
    let mut diff = 0u8;
    for (a, b) in expected.iter().zip(signature.iter()) {
        diff |= a ^ b;
    }
    diff == 0
}

/// Internal buffer for assembling signature data before verification.
/// Uses raw allocation for performance but maintains strict safety invariants.
struct SigBuffer {
    ptr: *mut u8,
    capacity: usize,
    len: usize,
}

impl SigBuffer {
    /// Allocates a signature buffer with the given capacity
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0 && capacity <= MAX_SIG_SIZE);
        let layout = std::alloc::Layout::from_size_align(capacity, 1).unwrap();
        let ptr = unsafe { std::alloc::alloc(layout) };
        if ptr.is_null() {
            std::alloc::handle_alloc_error(layout);
        }
        SigBuffer { ptr, capacity, len: 0 }
    }

    /// Copies data into the buffer with bounds checking
    fn append(&mut self, data: &[u8]) -> Result<(), &'static str> {
        if data.len() > self.capacity - self.len {
            return Err("append would overflow signature buffer");
        }
        unsafe {
            std::ptr::copy_nonoverlapping(
                data.as_ptr(),
                self.ptr.add(self.len),
                data.len(),
            );
        }
        self.len += data.len();
        Ok(())
    }

    fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
    }
}

impl Drop for SigBuffer {
    fn drop(&mut self) {
        let layout = std::alloc::Layout::from_size_align(self.capacity, 1).unwrap();
        unsafe { std::alloc::dealloc(self.ptr, layout); }
    }
}

/// Validates and extracts the signature length from the protocol header.
/// Returns the validated buffer size to allocate for signature processing.
fn compute_sig_buffer_size(raw_sig_len: u32, _version: u16) -> Result<usize, &'static str> {
    let size = raw_sig_len as usize;

    if size == 0 {
        return Err("signature length cannot be zero");
    }

    if size > MAX_SIG_SIZE {
        return Err("signature exceeds maximum allowed size");
    }

    Ok(size)
}

/// Parses and verifies a protocol message from raw bytes
pub fn parse_and_verify(input: &[u8], keystore: &KeyStore) -> Result<VerifiedMessage, String> {
    let mut cursor = Cursor::new(input);

    // Read magic
    let mut magic_bytes = [0u8; 4];
    cursor.read_exact(&mut magic_bytes).map_err(|e| format!("read magic: {}", e))?;
    let magic = u32::from_be_bytes(magic_bytes);
    if magic != MAGIC {
        return Err("invalid magic number".to_string());
    }

    // Read version
    let mut ver_bytes = [0u8; 2];
    cursor.read_exact(&mut ver_bytes).map_err(|e| format!("read version: {}", e))?;
    let version = u16::from_be_bytes(ver_bytes);
    if version != SUPPORTED_VERSION {
        return Err(format!("unsupported version: {}", version));
    }

    // Read signature length (4 bytes in protocol)
    let mut siglen_bytes = [0u8; 4];
    cursor.read_exact(&mut siglen_bytes).map_err(|e| format!("read sig_len: {}", e))?;
    let raw_sig_len = u32::from_be_bytes(siglen_bytes);

    // Validate and compute buffer size (uses full u32 value, no truncation)
    let buffer_size = compute_sig_buffer_size(raw_sig_len, version)
        .map_err(|e| e.to_string())?;

    // Read signature data - length matches validated buffer_size
    let sig_data_len = buffer_size;
    if cursor.position() as usize + sig_data_len > input.len() {
        return Err("signature data exceeds input".to_string());
    }

    let sig_start = cursor.position() as usize;
    let sig_data = &input[sig_start..sig_start + sig_data_len];
    cursor.set_position((sig_start + sig_data_len) as u64);

    // Allocate buffer and copy with bounds checking
    let mut sig_buf = SigBuffer::new(buffer_size);
    sig_buf.append(sig_data)
        .map_err(|e| e.to_string())?;

    // Read remaining payload
    let payload_start = cursor.position() as usize;
    let payload = input[payload_start..].to_vec();

    if payload.len() > MAX_PAYLOAD_SIZE {
        return Err("payload too large".to_string());
    }

    // Verify signature
    let key = keystore.get_key(version)
        .ok_or_else(|| "no key for version".to_string())?;
    let valid = verify_signature(&payload, sig_buf.as_slice(), key);

    Ok(VerifiedMessage {
        payload,
        signature_valid: valid,
        version,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_message() {
        let keystore = KeyStore::new();
        let mut msg = Vec::new();
        msg.extend_from_slice(&MAGIC.to_be_bytes());
        msg.extend_from_slice(&SUPPORTED_VERSION.to_be_bytes());
        let sig = vec![0xAA; 32];
        msg.extend_from_slice(&(sig.len() as u32).to_be_bytes());
        msg.extend_from_slice(&sig);
        msg.extend_from_slice(b"hello world");

        let result = parse_and_verify(&msg, &keystore);
        assert!(result.is_ok());
    }

    #[test]
    fn test_zero_sig_rejected() {
        let keystore = KeyStore::new();
        let mut msg = Vec::new();
        msg.extend_from_slice(&MAGIC.to_be_bytes());
        msg.extend_from_slice(&SUPPORTED_VERSION.to_be_bytes());
        msg.extend_from_slice(&0u32.to_be_bytes());
        msg.extend_from_slice(b"payload");

        let result = parse_and_verify(&msg, &keystore);
        assert!(result.is_err());
    }

    #[test]
    fn test_oversized_sig_rejected() {
        let keystore = KeyStore::new();
        let mut msg = Vec::new();
        msg.extend_from_slice(&MAGIC.to_be_bytes());
        msg.extend_from_slice(&SUPPORTED_VERSION.to_be_bytes());
        msg.extend_from_slice(&0x00010020u32.to_be_bytes()); // Would overflow if truncated
        msg.extend_from_slice(&vec![0xBB; 100]);

        let result = parse_and_verify(&msg, &keystore);
        assert!(result.is_err()); // Rejected because > MAX_SIG_SIZE
    }
}
